#include <print>
#include <map>
#include <string>
#include <utility>
#include <vector>
#include <algorithm>

int main() {
    std::pair<std::string, int> p = {"数学", 92};
    std::println("first = {} second = {}", p.first, p.second);
    auto [subject, score] = p;
    std::println("拆开: {} = {}", subject, score);
    std::vector<std::pair<int, std::string>> ranked = {
        {95, "小红"}, {95, "小明"}, {88, "小强"}, {72, "小美"}};
    std::sort(ranked.begin(), ranked.end(),
              [](const std::pair<int, std::string>& a, const std::pair<int, std::string>& b) {
                  if (a.first != b.first) return a.first > b.first;
                  return a.second < b.second;
              });
    for (const auto& [sc, name] : ranked)
        std::println("{} {}", name, sc);
    std::map<std::string, int> freq = {{"cat", 3}, {"dog", 2}, {"owl", 1}};
    for (const auto& [word, count] : freq)
        std::println("{} 出现 {} 次", word, count);
    return 0;
}

